<?php
declare(strict_types=1);

use App\Core\{App,Request};
use App\Repositories\{AcademicRepository,WorkflowRepository};
use App\Services\{CredentialService,SmsSettingsService};

return static function(App$app):array{
    $out=[];$check=static function(string$n,bool$v)use(&$out):void{$out[$n]=$v;};$db=$app->database();$pdo=$db->connection();
    $institute=(int)$db->query('SELECT id FROM institutes ORDER BY id LIMIT 1')->fetchColumn();$admin=(int)$db->query('SELECT u.id FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE r.slug="admin" LIMIT 1')->fetchColumn();
    $academic=new AcademicRepository($db);$suffix=substr(bin2hex(random_bytes(4)),0,8);$academic->createClass($institute,'Flow A '.$suffix,1000,null);$academic->createClass($institute,'Flow B '.$suffix,1000,null);$from=(int)$db->query('SELECT id FROM classes WHERE institute_id=:i AND name=:n',['i'=>$institute,'n'=>'Flow A '.$suffix])->fetchColumn();$to=(int)$db->query('SELECT id FROM classes WHERE institute_id=:i AND name=:n',['i'=>$institute,'n'=>'Flow B '.$suffix])->fetchColumn();$academic->assign($institute,$from,'Math '.$suffix,100);$subject=(int)$db->query('SELECT s.id FROM subjects s JOIN class_subjects cs ON cs.subject_id=s.id WHERE cs.class_id=:c',['c'=>$from])->fetchColumn();
    $now=date('Y-m-d H:i:s');$db->query('INSERT INTO students(institute_id,class_id,registration_no,student_name,date_of_admission,created_at,updated_at) VALUES(:i,:c,:r,:n,:d,:x,:x2)',['i'=>$institute,'c'=>$from,'r'=>'FLOW-'.$suffix,'n'=>'Flow Student','d'=>date('Y-m-d'),'x'=>$now,'x2'=>$now]);$student=(int)$pdo->lastInsertId();$db->query('INSERT INTO employees(institute_id,employee_no,name,joining_date,role,monthly_salary,status,created_at,updated_at) VALUES(:i,:e,:n,:d,"Teacher",50000,"active",:x,:x2)',['i'=>$institute,'e'=>'EMP-FLOW-'.$suffix,'n'=>'Flow Teacher','d'=>date('Y-m-d'),'x'=>$now,'x2'=>$now]);$employee=(int)$pdo->lastInsertId();
    $w=new WorkflowRepository($db);
    $promoted=$w->promote($institute,$from,$to,[$student],$admin);$check('promotion persists class and history',$promoted===1&&(int)$db->query('SELECT class_id FROM students WHERE id=:id',['id'=>$student])->fetchColumn()===$to&&(int)$db->query('SELECT COUNT(*) FROM student_promotions WHERE student_id=:id',['id'=>$student])->fetchColumn()===1);
    try{$w->promote($institute,$from,$to,[$student],$admin);$invalid=false;}catch(DomainException){$invalid=true;}$check('invalid promotion rolls back',$invalid&&(int)$db->query('SELECT class_id FROM students WHERE id=:id',['id'=>$student])->fetchColumn()===$to);
    $salary=$w->paySalary($institute,$employee,date('Y-m'),50000,date('Y-m-d'),$admin);$check('salary payment and slip persist',$salary>0&&$w->salarySlip($salary,$institute)['name']==='Flow Teacher');try{$w->paySalary($institute,$employee,date('Y-m'),50000,date('Y-m-d'),$admin);$duplicate=false;}catch(DomainException){$duplicate=true;}$check('duplicate salary period rejected',$duplicate);
    $credential=(new CredentialService($db))->create('student',$student,$institute,'student.'.$suffix.'@example.test',$admin);$hash=(string)$db->query('SELECT password_hash FROM users WHERE id=:id',['id'=>$credential['user_id']])->fetchColumn();$check('credential is hashed and one-time value verifies',$hash!==$credential['temporary_password']&&password_verify($credential['temporary_password'],$hash));
    $exam=$w->createExam($institute,'Term '.$suffix,date('Y-m-d'),date('Y-m-d',strtotime('+7 days')),$admin);$setup=$w->setupExam($institute,$exam,$from,$subject,100);$db->query('UPDATE students SET class_id=:c WHERE id=:s',['c'=>$from,'s'=>$student]);$w->saveExamMarks($institute,$setup,[$student=>87],$admin);$result=$w->studentResult($institute,$exam,$student);$check('exam setup marks and result persist',(float)$result['obtained']===87.0&&(float)$result['total']===100.0);try{$w->saveExamMarks($institute,$setup,[$student=>101],$admin);$bounds=false;}catch(DomainException){$bounds=true;}$check('exam mark bounds enforced',$bounds&&(float)$db->query('SELECT obtained_marks FROM exam_marks WHERE exam_subject_id=:e AND student_id=:s',['e'=>$setup,'s'=>$student])->fetchColumn()===87.0);
    $homework=$w->createHomework($institute,['date'=>date('Y-m-d'),'teacher_id'=>$employee,'class_id'=>$from,'subject_id'=>$subject,'text'=>'Chapter 4 exercises'],$admin);$check('homework persists validated relationships',$homework>0);
    $test=$w->createClassTest($institute,$from,$subject,date('Y-m-d'),'Quiz '.$suffix,20,$admin);$w->saveClassTestMarks($institute,$test,[$student=>18],$admin);$check('class test marks persist',(float)$db->query('SELECT obtained_marks FROM class_test_marks WHERE class_test_id=:t AND student_id=:s',['t'=>$test,'s'=>$student])->fetchColumn()===18.0);
    $certificate=$w->createCertificate($institute,'achievement','student',$student,null,date('Y-m-d'),$admin,'Excellent progress');$check('certificate recipient persists',$certificate>0);try{$w->createCertificate($institute,'x','student',$student,$employee,date('Y-m-d'),$admin,null);$badRecipient=false;}catch(DomainException){$badRecipient=true;}$check('invalid certificate recipient rejected',$badRecipient);
    $conversation=$w->createConversation($institute,$admin,(int)$credential['user_id'],'Welcome');$message=$w->sendMessage($institute,$conversation,(int)$credential['user_id'],'Thank you');$check('messaging participant access persists',$message>0);$other=(int)$db->query('SELECT id FROM users WHERE id NOT IN (:a,:b) LIMIT 1',['a'=>$admin,'b'=>$credential['user_id']])->fetchColumn();if($other){try{$w->sendMessage($institute,$conversation,$other,'leak');$denied=false;}catch(DomainException){$denied=true;}$check('messaging blocks non-participant',$denied);}
    $sms=new SmsSettingsService($db,'test-key-'.$suffix);$sms->save($institute,null,false,[],null,$admin);$sms->save($institute,'future-adapter',true,['sender'=>'School'],'secret-'.$suffix,$admin);$masked=$sms->masked($institute);$check('SMS secret stored masked',$masked['secret_masked']==='********'.substr('secret-'.$suffix,-4)&&!str_contains(json_encode($masked),'secret-'.$suffix));
    $live=$w->createLiveClass($institute,['title'=>'Math review','code'=>'ROOM-'.$suffix,'type'=>'SC','class'=>$from,'schedule'=>1,'date'=>date('Y-m-d',strtotime('+1 day')),'time'=>'10:00','duration'=>45],$admin);$check('live class schedule persists',$live>0);
    $app->session()->set('auth_user',['id'=>$admin,'name'=>'Admin','email'=>'admin@test','status'=>'active','roles'=>['admin'],'permissions'=>['*']]);$csrf=$app->run(new Request([],['employee_id'=>$employee],[],['REQUEST_METHOD'=>'POST','REQUEST_URI'=>'/admin/salary/pay']));$check('new workflow CSRF enforced',$csrf->status()===419);
    return$out;
};
